// a 3-line security habit: check before you trust
function openDashboard(user) {
  if (!user) return "Please log in first";
  return "Welcome back, " + user.name;
}

// confidentiality: only the message owner reads it
function canReadMessage(user, message) {
  return user.id === message.ownerId; // not you? not your eyes.
}

// integrity: prices change only through the approved path
function setPrice(product, newPrice, user) {
  if (user.role !== "admin") return "Denied";
  if (newPrice <= 0) return "Invalid price";
  product.price = newPrice;
  return "Price updated";
}

// availability: cap how often one user can ask
const hits = {};
function canRequest(userId) {
  hits[userId] = (hits[userId] || 0) + 1;
  return hits[userId] <= 100; // slow down after 100 requests
}

// crown jewels for a gig app: rank what hurts most
const assets = [
  { name: "user passwords", impact: "critical" },
  { name: "payment details", impact: "critical" },
  { name: "profile photos", impact: "low" },
];

// every door gets a check — no exceptions
function handleSearch(query) {
  if (typeof query !== "string" || query.length > 100) {
    return "Invalid search";
  }
  return "Searching for: " + query;
}

// layers working together
function deleteAccount(user, targetId) {
  if (!user) return "Denied";                // layer 1: logged in?
  if (user.id !== targetId) return "Denied"; // layer 2: is it yours?
  log("account deleted", user.id);           // layer 3: leave a trail
  return "Deleted";
}
